import './App.css';
import './AppBingo.css';
import { useState } from 'react';

// Generate one random Bingo card
function getBingoLetter(number) {
  if (number >= 1 && number <= 15) {
    return 'B';
  } else if (number >= 16 && number <= 30) {
    return 'I';
  } else if (number >= 31 && number <= 45) {
    return 'N';
  } else if (number >= 46 && number <= 60) {
    return 'G';
  } else if (number >= 61 && number <= 75) {
    return 'O';
  }

  return '';
}

function generateCard() {
  const ranges = [
    [1, 15],
    [16, 30],
    [31, 45],
    [46, 60],
    [61, 75]
  ];

  const columns = ranges.map(([min, max], colIndex) => {
    const numbers = [];

    while (numbers.length < 5) {
      const number =
        Math.floor(Math.random() * (max - min + 1)) + min;

      if (!numbers.includes(number)) {
        numbers.push(number);
      }
    }

    // The center of every Bingo card is FREE
    if (colIndex === 2) {
      numbers[2] = 'FREE';
    }

    return numbers;
  });

  // Convert columns into rows
  return Array.from({ length: 5 }, (_, rowIndex) =>
    columns.map(column => column[rowIndex])
  );
}

// Generate three Bingo cards
function generateThreeCards() {
  return [
    generateCard(),
    generateCard(),
    generateCard()
  ];
}

// Check whether one card has a winning pattern
function getWinningPattern(card, calledNumbers) {
  const isMarked = (cell) =>
    cell === 'FREE' || calledNumbers.includes(cell);

  // 1. Check horizontal rows
  for (let row = 0; row < 5; row++) {
    if (card[row].every(isMarked)) {
      return 'Horizontal Row';
    }
  }

  // 2. Check vertical columns
  for (let col = 0; col < 5; col++) {
    const completed = card.every(row => isMarked(row[col]));

    if (completed) {
      return 'Vertical Column';
    }
  }

  // 3. Check diagonal from top-left to bottom-right
  const diagonalOne = [0, 1, 2, 3, 4].every(index =>
    isMarked(card[index][index])
  );

  if (diagonalOne) {
    return 'Diagonal';
  }

  // 4. Check diagonal from top-right to bottom-left
  const diagonalTwo = [0, 1, 2, 3, 4].every(index =>
    isMarked(card[index][4 - index])
  );

  if (diagonalTwo) {
    return 'Diagonal';
  }

  // 5. Check four corners
  const corners = [
    card[0][0],
    card[0][4],
    card[4][0],
    card[4][4]
  ];

  if (corners.every(isMarked)) {
    return 'Four Corners';
  }

  return null;
}

// Find the first winning card
function findWinningCard(cards, calledNumbers) {
  for (let index = 0; index < cards.length; index++) {
    const pattern = getWinningPattern(cards[index], calledNumbers);

    if (pattern) {
      return {
        cardIndex: index,
        pattern: pattern
      };
    }
  }

  return null;
}

// Load saved statistics
function loadStats() {
  try {
    const savedStats = localStorage.getItem('bingoStats');

    if (savedStats) {
      return {
        totalGames: 0,
        playerWins: 0,
        botWins: 0,
        ties: 0,
        ...JSON.parse(savedStats)
      };
    }
  } catch (error) {
    console.error('Unable to load statistics:', error);
  }

  return {
    totalGames: 0,
    playerWins: 0,
    botWins: 0,
    ties: 0
  };
}

// Main Bingo component
function Bingo() {

  const [called, setCalled] = useState([]);

  const [remainingNumbers, setRemainingNumbers] = useState(
    Array.from({ length: 75 }, (_, index) => index + 1)
  );

  const [lastNumber, setLastNumber] = useState(null);

  const [playerCards, setPlayerCards] = useState(() =>
    generateThreeCards()
  );

  const [botCards, setBotCards] = useState(() =>
    generateThreeCards()
  );

  const [winner, setWinner] = useState(null);

  const [stats, setStats] = useState(loadStats);

  // Draw a random number
  const drawNumber = () => {

    if (remainingNumbers.length === 0 || winner) {
      return;
    }

    const randomIndex = Math.floor(
      Math.random() * remainingNumbers.length
    );

    const number = remainingNumbers[randomIndex];

    const updatedCalled = [...called, number];

    // Update called numbers
    setCalled(updatedCalled);
    setLastNumber(number);

    // Remove the drawn number
    setRemainingNumbers(previous =>
      previous.filter(n => n !== number)
    );

    // Check player cards
    const playerResult = findWinningCard(
      playerCards,
      updatedCalled
    );

    // Check bot cards
    const botResult = findWinningCard(
      botCards,
      updatedCalled
    );

    // Determine the winner
    if (playerResult && botResult) {

      setWinner({
        side: 'tie',
        playerCardIndex: playerResult.cardIndex,
        botCardIndex: botResult.cardIndex,
        pattern: playerResult.pattern
      });

      recordResult('tie');

    } else if (playerResult) {

      setWinner({
        side: 'player',
        playerCardIndex: playerResult.cardIndex,
        pattern: playerResult.pattern
      });

      recordResult('player');

    } else if (botResult) {

      setWinner({
        side: 'bot',
        botCardIndex: botResult.cardIndex,
        pattern: botResult.pattern
      });

      recordResult('bot');
    }
  };

  // Save the game result
  const recordResult = (result) => {

    const updatedStats = {
      ...stats,
      totalGames: stats.totalGames + 1
    };

    if (result === 'player') {
      updatedStats.playerWins++;
    } else if (result === 'bot') {
      updatedStats.botWins++;
    } else {
      updatedStats.ties++;
    }

    setStats(updatedStats);

    localStorage.setItem(
      'bingoStats',
      JSON.stringify(updatedStats)
    );
  };

  // Start a completely new game
  const newGame = () => {

    setCalled([]);

    setRemainingNumbers(
      Array.from({ length: 75 }, (_, index) => index + 1)
    );

    setLastNumber(null);

    setWinner(null);

    // Generate new Bingo cards
    setPlayerCards(generateThreeCards());
    setBotCards(generateThreeCards());
  };

  // Reset saved statistics
  const resetStats = () => {

    const emptyStats = {
      totalGames: 0,
      playerWins: 0,
      botWins: 0,
      ties: 0
    };

    setStats(emptyStats);

    localStorage.setItem(
      'bingoStats',
      JSON.stringify(emptyStats)
    );
  };

  // Display a single Bingo card
  const renderCard = (card, cardIndex, side) => {

    const winningCard =
      winner &&
      (
        (side === 'player' &&
          winner.playerCardIndex === cardIndex) ||
        (side === 'bot' &&
          winner.botCardIndex === cardIndex)
      );

    return (
      <div
        className={`bingo-card ${
          winningCard ? 'winning-card' : ''
        }`}
        key={`${side}-${cardIndex}`}
      >

        <div className="card-heading">
          {side === 'player' ? 'Player' : 'Bot'} Card {cardIndex + 1}

          {winningCard && (
            <span className="winner-tag">WINNER</span>
          )}
        </div>

        <table>
          <thead>
            <tr>
              {['B', 'I', 'N', 'G', 'O'].map(letter => (
                <th key={letter}>{letter}</th>
              ))}
            </tr>
          </thead>

          <tbody>
            {card.map((row, rowIndex) => (
              <tr key={rowIndex}>

                {row.map((cell, colIndex) => {

                  const isMarked =
                    cell === 'FREE' || called.includes(cell);

                  return (
                    <td
                      key={colIndex}
                      className={isMarked ? 'marked' : ''}
                    >
                      {cell}
                    </td>
                  );
                })}

              </tr>
            ))}
          </tbody>
        </table>

      </div>
    );
  };

  // Organize numbers into B-I-N-G-O columns
  const numberRanges = [
    { letter: 'B', start: 1, end: 15 },
    { letter: 'I', start: 16, end: 30 },
    { letter: 'N', start: 31, end: 45 },
    { letter: 'G', start: 46, end: 60 },
    { letter: 'O', start: 61, end: 75 }
  ];

  return (
    <div className="App">

      <main className="App-header bingo-page">

        <div className="bingo-container">

          {/* Page Header */}
          <header className="page-header">
            <h1>BINGO</h1>
            <p>Player vs. Bot</p>
          </header>

          {/* Game Result */}
          {winner && (
            <div className="winner-message">

              {winner.side === 'player' && (
                <>
                  <h2>Congratulations! You Win!</h2>
                  <p>You completed a {winner.pattern}.</p>
                </>
              )}

              {winner.side === 'bot' && (
                <>
                  <h2>The Bot Wins!</h2>
                  <p>The bot completed a {winner.pattern}.</p>
                </>
              )}

              {winner.side === 'tie' && (
                <>
                  <h2>It's a Tie!</h2>
                  <p>Both completed a Bingo pattern!</p>
                </>
              )}

            </div>
          )}

          {/* Game Layout */}
          <div className="game-layout">

            {/* Main Game Area */}
            <section className="game-main">

              {/* Number Randomizer */}
              <div className="game-panel randomizer">

                <h2>Number Randomizer</h2>

                <div className="last-number">
                  {lastNumber !== null
                  ? `${getBingoLetter(lastNumber)}-${lastNumber}`
                  : '--'}
                </div>

                <p>
                  Numbers Called: {called.length}/75
                </p>

                <div className="game-buttons">

                  <button
                    className="primary-button"
                    onClick={drawNumber}
                    disabled={
                      remainingNumbers.length === 0 ||
                      winner !== null
                    }
                  >
                    Draw Bingo Number
                  </button>

                  <button
                    className="secondary-button"
                    onClick={newGame}
                  >
                    New Game
                  </button>

                </div>

                {winner && (
                  <p className="game-over">
                    Game Over! Start a new game to play again.
                  </p>
                )}

                {remainingNumbers.length === 0 && !winner && (
                  <p className="game-over">
                    All numbers have been called.
                  </p>
                )}

              </div>

              {/* Player Cards */}
              <section className="cards-section">

                <h2>Your Cards</h2>

                <div className="cards-container">
                  {playerCards.map((card, index) =>
                    renderCard(card, index, 'player')
                  )}
                </div>

              </section>

              {/* Bot Cards */}
              <section className="cards-section">

                <h2>Bot Cards</h2>

                <div className="cards-container">
                  {botCards.map((card, index) =>
                    renderCard(card, index, 'bot')
                  )}
                </div>

              </section>

            </section>

            {/* Sidebar */}
            <aside className="game-sidebar">

              {/* Last Called Numbers */}
              <div className="game-panel">

                <h2>Called Numbers</h2>

                <div className="called-list">

                  {called.length === 0 ? (
                    <p>No numbers called yet.</p>
                  ) : (
                    [...called].reverse().map((number, index) => (
                      <span
                        key={number}
                        className={
                          index === 0
                            ? 'called-number latest'
                            : 'called-number'
                        }
                      >
                        {number}
                      </span>
                    ))
                  )}

                </div>

              </div>

              {/* Full Number History */}
              <div className="game-panel">

                <h2>Number History</h2>

                <div className="history-board">

                  {numberRanges.map(range => (

                    <div className="history-column" key={range.letter}>

                      <div className="history-letter">
                        {range.letter}
                      </div>

                      {Array.from(
                        { length: 15 },
                        (_, index) => range.start + index
                      ).map(number => (

                        <div
                          key={number}
                          className={
                            called.includes(number)
                              ? 'history-number called'
                              : 'history-number'
                          }
                        >
                          {number}
                        </div>

                      ))}

                    </div>

                  ))}

                </div>

                <p className="history-note">
                  Highlighted numbers have already been called.
                </p>

              </div>

              {/* Game Statistics */}
              <div className="game-panel statistics-panel">

                <h2>Game Statistics</h2>

                <div className="stat-item">
                  <span>Total Games</span>
                  <strong>{stats.totalGames}</strong>
                </div>

                <div className="stat-item">
                  <span>Player Wins</span>
                  <strong>{stats.playerWins}</strong>
                </div>

                <div className="stat-item">
                  <span>Bot Wins</span>
                  <strong>{stats.botWins}</strong>
                </div>

                <div className="stat-item">
                  <span>Ties</span>
                  <strong>{stats.ties}</strong>
                </div>

                <button
                  className="reset-stats-button"
                  onClick={resetStats}
                >
                  Reset Statistics
                </button>

              </div>

            </aside>

          </div>

          <footer className="bingo-footer">
            Bingo Game | EDP Project Group 6
          </footer>

        </div>

      </main>

    </div>
  );
}

export default Bingo;
